\documentclass[11pt]{article}

\title{Soil Acidification and Microbial Community Shifts under Long-Term Tea Cultivation}
\author{Y.~Abe and F.~Nakamura}
\date{April 2026}

\begin{document}
\maketitle

\begin{abstract}
Long-term tea cultivation acidifies the rhizosphere through root
exudation and ammonium-based fertilisation. We sampled soils from
chronosequences of 5, 18, and 34 years of cultivation and measured pH,
exchangeable aluminium, and bacterial community composition.
\end{abstract}

